	(1, NULL, 'Laptop', 'laptop', 'http://localhost:8080/uploads/categories/laptop.png', 'Máy tính xách tay chính hãng từ Apple, ASUS, Dell, HP, Lenovo, MSI, Acer', 1, 'active', NULL),
	(2, NULL, 'Máy tính để bàn (PC)', 'may-tinh-de-ban-pc', 'http://localhost:8080/uploads/categories/may-tinh-de-ban-pc.png', 'PC Gaming đồng bộ, Máy tính All-in-One, Workstation và Mac Desktop', 2, 'active', NULL),
	(3, NULL, 'Màn hình máy tính', 'man-hinh-may-tinh', 'http://localhost:8080/uploads/categories/man-hinh-may-tinh.png', 'Màn hình Gaming 144Hz - 240Hz, Đồ họa 4K IPS, Màn hình cong và văn phòng', 3, 'active', NULL),
	(4, NULL, 'Linh kiện máy tính', 'linh-kien-may-tinh', 'http://localhost:8080/uploads/categories/linh-kien-may-tinh.png', 'Phần cứng build PC: CPU, VGA, RAM, SSD, Mainboard, Nguồn, Tản nhiệt, Vỏ Case', 4, 'active', NULL),
	(5, NULL, 'Phụ kiện & Thiết bị ngoại vi', 'phu-kien-thiet-bi-ngoai-vi', 'http://localhost:8080/uploads/categories/phu-kien-thiet-bi-ngoai-vi.png', 'Bàn phím cơ, Chuột gaming, Tai nghe, Webcam, Cáp sạc & Hub chuyển đổi', 5, 'active', NULL),
