	(7, 1, 'Laptop Gaming', 'laptop-gaming', 'http://localhost:8080/uploads/categories/laptop-gaming.png', 'Laptop gaming cấu hình khủng, màn hình 144Hz, tản nhiệt cao cấp', 2, 'active', NULL),
	(8, 1, 'Laptop Văn phòng - Sinh viên', 'laptop-van-phong-sinh-vien', 'http://localhost:8080/uploads/categories/laptop-van-phong-sinh-vien.png', 'Laptop mỏng nhẹ, thời lượng pin dài, giá thành tối ưu cho học tập và làm việc', 3, 'active', NULL),
	(9, 1, 'Laptop Đồ họa - Kỹ thuật', 'laptop-do-hoa-ky-thuat', 'http://localhost:8080/uploads/categories/laptop-do-hoa-ky-thuat.png', 'Laptop màn hình chuẩn màu 100% sRGB/DCI-P3, cấu hình mạnh cho Designer & Dev', 4, 'active', NULL),
	(10, 1, 'Laptop Mỏng nhẹ Cao cấp', 'laptop-mong-nhe-cao-cap', 'http://localhost:8080/uploads/categories/laptop-mong-nhe-cao-cap.jpg', 'Laptop doanh nhân siêu mỏng nhẹ, vỏ nhôm nguyên khối dưới 1.3kg', 5, 'active', NULL),
	(11, 1, 'Laptop Cảm ứng 2 trong 1', 'laptop-cam-ung-2-trong-1', 'http://localhost:8080/uploads/categories/laptop-cam-ung-2-trong-1.png', 'Laptop xoay gập 360 độ kèm bút cảm ứng tiện lợi', 6, 'active', NULL),
	(12, 2, 'Máy tính All-in-One (AIO)', 'may-tinh-all-in-one', 'http://localhost:8080/uploads/categories/may-tinh-all-in-one.png', 'Máy tính liền màn hình gọn gàng, tiết kiệm không gian', 1, 'active', NULL),
	(13, 2, 'PC Gaming & Streamer', 'pc-gaming-streamer', 'http://localhost:8080/uploads/categories/pc-gaming-streamer.png', 'Dàn PC Gaming lắp sẵn LED RGB tối ưu hiệu năng chiến game nặng', 2, 'active', NULL),
	(14, 2, 'PC Đồ họa & Workstation', 'pc-do-hoa-workstation', 'http://localhost:8080/uploads/categories/pc-do-hoa-workstation.png', 'Máy trạm chuyên dụng dựng phim 3D, Render kiến trúc và AI Computing', 3, 'active', NULL),
	(15, 2, 'PC Văn phòng & Doanh nghiệp', 'pc-van-phong-doanh-nghiep', 'http://localhost:8080/uploads/categories/pc-van-phong-doanh-nghiep.png', 'Máy tính để bàn đồng bộ nhỏ gọn, bền bỉ cho văn phòng', 4, 'active', NULL),
