	(19, 3, 'Màn hình Văn phòng', 'man-hinh-van-phong', 'http://localhost:8080/uploads/categories/man-hinh-van-phong.png', 'Màn hình hiển thị chống chói bảo vệ mắt cho công việc hàng ngày', 3, 'active', NULL),
