	(23, 4, 'RAM - Bộ nhớ trong', 'ram-bo-nho-trong', 'http://localhost:8080/uploads/categories/ram-bo-nho-trong.png', 'RAM DDR4, DDR5 tốc độ cao có tản nhiệt RGB', 3, 'active', NULL),
