	(77, 28, 1, 2, 'Chuột không dây Apple Magic Mouse (Multi-Touch Surface)', 'chuot-khong-day-apple-magic-mouse-multi-touch-surface', 'HW-1021', 'Bề mặt cảm ứng đa điểm vuốt mượt mà trên macOS, cổng sạc USB-C.', '<h3>Đặc điểm nổi bật của Chuột không dây Apple Magic Mouse (Multi-Touch Surface)</h3><p>Bề mặt cảm ứng đa điểm vuốt mượt mà trên macOS, cổng sạc USB-C.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 12 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 12, 'active', 812, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(78, 29, 12, 3, 'Tai nghe Gaming không dây Logitech G733 LIGHTSPEED RGB Wireless', 'tai-nghe-gaming-khong-day-logitech-g733-lightspeed-rgb-wireless', 'HW-1022', 'Tai nghe không dây siêu nhẹ 278g, màng loa PRO-G 40mm và công nghệ lọc âm Blue VO!CE.', '<h3>Đặc điểm nổi bật của Tai nghe Gaming không dây Logitech G733 LIGHTSPEED RGB Wireless</h3><p>Tai nghe không dây siêu nhẹ 278g, màng loa PRO-G 40mm và công nghệ lọc âm Blue VO!CE.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 24 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 24, 'active', 212, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(79, 29, 29, 4, 'Loa máy tính để bàn Edifier G2000 Gaming Hi-Res RGB 32W', 'loa-may-tinh-de-ban-edifier-g2000-gaming-hi-res-rgb-32w', 'HW-1023', 'Cặp loa Gaming để bàn công suất 32W Peak, âm trầm mạnh mẽ và 12 chế độ LED RGB.', '<h3>Đặc điểm nổi bật của Loa máy tính để bàn Edifier G2000 Gaming Hi-Res RGB 32W</h3><p>Cặp loa Gaming để bàn công suất 32W Peak, âm trầm mạnh mẽ và 12 chế độ LED RGB.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 12 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 12, 'active', 101, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(80, 30, 30, 3, 'Củ sạc nhanh Anker 735 Charger GaNPrime 65W 3 Cổng (2C1A)', 'cu-sac-nhanh-anker-735-charger-ganprime-65w-3-cong-2c1a', 'HW-1024', 'Công nghệ GaNPrime độc quyền sạc nhanh cùng lúc cho Laptop, iPad và iPhone siêu nhỏ gọn.', '<h3>Đặc điểm nổi bật của Củ sạc nhanh Anker 735 Charger GaNPrime 65W 3 Cổng (2C1A)</h3><p>Công nghệ GaNPrime độc quyền sạc nhanh cùng lúc cho Laptop, iPad và iPhone siêu nhỏ gọn.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 18 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 18, 'active', 750, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(81, 30, 30, 4, 'Hub chuyển đổi USB-C HyperDrive 8-in-1 Dual 4K HDMI cho MacBook & Laptop', 'hub-chuyen-doi-usb-c-hyperdrive-8-in-1-dual-4k-hdmi-cho-macbook-laptop', 'HW-1025', 'Mở rộng 8 cổng đa năng: 2x HDMI 4K@60Hz, USB-C 100W PD, 2x USB-A 10Gbps, SD/microSD, Gigabit LAN.', '<h3>Đặc điểm nổi bật của Hub chuyển đổi USB-C HyperDrive 8-in-1 Dual 4K HDMI cho MacBook & Laptop</h3><p>Mở rộng 8 cổng đa năng: 2x HDMI 4K@60Hz, USB-C 100W PD, 2x USB-A 10Gbps, SD/microSD, Gigabit LAN.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 24 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 24, 'active', 1387, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(82, 31, 25, 2, 'Hệ điều hành Microsoft Windows 11 Pro 64-bit Bản quyền Vĩnh viễn (FPP Box)', 'he-dieu-hanh-microsoft-windows-11-pro-64-bit-ban-quyen-vinh-vien-fpp-box', 'HW-1026', 'Bản quyền Windows 11 Pro trọn đời, hỗ trợ chuyển đổi sang máy tính khác, đầy đủ tính năng bảo mật BitLocker và Hyper-V.', '<h3>Đặc điểm nổi bật của Hệ điều hành Microsoft Windows 11 Pro 64-bit Bản quyền Vĩnh viễn (FPP Box)</h3><p>Bản quyền Windows 11 Pro trọn đời, hỗ trợ chuyển đổi sang máy tính khác, đầy đủ tính năng bảo mật BitLocker và Hyper-V.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 36 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 36, 'active', 1311, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(83, 31, 25, 3, 'Phần mềm Microsoft 365 Personal (1 Năm - 1 Người dùng, 1TB Cloud OneDrive)', 'phan-mem-microsoft-365-personal-1-nam-1-nguoi-dung-1tb-cloud-onedrive', 'HW-1027', 'Trọn bộ ứng dụng văn phòng bản quyền Word, Excel, PowerPoint, Outlook mới nhất kèm 1000GB lưu trữ đám mây OneDrive.', '<h3>Đặc điểm nổi bật của Phần mềm Microsoft 365 Personal (1 Năm - 1 Người dùng, 1TB Cloud OneDrive)</h3><p>Trọn bộ ứng dụng văn phòng bản quyền Word, Excel, PowerPoint, Outlook mới nhất kèm 1000GB lưu trữ đám mây OneDrive.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 12 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 12, 'active', 722, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(84, 31, 25, 4, 'Phần mềm Microsoft Office Home & Student 2024 Vĩnh viễn cho 1 PC / Mac', 'phan-mem-microsoft-office-home-student-2024-vinh-vien-cho-1-pc-mac', 'HW-1028', 'Bản quyền Word, Excel, PowerPoint 2024 mua một lần dùng mãi mãi cho sinh viên và gia đình.', '<h3>Đặc điểm nổi bật của Phần mềm Microsoft Office Home & Student 2024 Vĩnh viễn cho 1 PC / Mac</h3><p>Bản quyền Word, Excel, PowerPoint 2024 mua một lần dùng mãi mãi cho sinh viên và gia đình.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 36 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 36, 'active', 849, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL),
	(85, 31, 28, 4, 'Phần mềm diệt virus Kaspersky Plus 1 Thiết bị (Bản quyền 1 Năm)', 'phan-mem-diet-virus-kaspersky-plus-1-thiet-bi-ban-quyen-1-nam', 'HW-1029', 'Bảo vệ toàn diện máy tính khỏi mã độc tống tiền Ransomware, virus, bảo mật giao dịch ngân hàng và VPN không giới hạn.', '<h3>Đặc điểm nổi bật của Phần mềm diệt virus Kaspersky Plus 1 Thiết bị (Bản quyền 1 Năm)</h3><p>Bảo vệ toàn diện máy tính khỏi mã độc tống tiền Ransomware, virus, bảo mật giao dịch ngân hàng và VPN không giới hạn.</p><p>Sản phẩm phân phối chính hãng 100%, bảo hành 12 tháng tiêu chuẩn, 1 đổi 1 trong 30 ngày nếu có lỗi do nhà sản xuất.</p>', 12, 'active', 1462, '2026-08-24 10:24:02', '2026-08-24 10:24:02', NULL);
