	(30, 'POLICY_FAQ_JSON', '[{"id":1,"category":"order","question":"Tôi có bắt buộc phải tạo tài khoản để mua hàng không?","answer":"Không bắt buộc. Quý khách hoàn toàn có thể mua hàng với tư cách Khách vãng lai (Guest Checkout) chỉ bằng cách nhập thông tin họ tên, số điện thoại và địa chỉ nhận hàng."},{"id":2,"category":"order","question":"Đơn hàng chưa thanh toán chuyển khoản sẽ được giữ trong bao lâu?","answer":"Đơn hàng chọn phương thức chuyển khoản sẽ được giữ linh kiện trong 24 giờ trước khi tự động hủy hoàn kho."},{"id":3,"category":"shipping","question":"Làm thế nào để tôi kiểm tra tình trạng vận chuyển đơn hàng của mình?","answer":"Quý khách truy cập vào mục \\"Tra cứu đơn hàng\\", nhập Mã đơn hàng và Số điện thoại để theo dõi lộ trình thời gian thực."},{"id":4,"category":"shipping","question":"Tôi có được quyền kiểm tra hàng trước khi thanh toán (đồng kiểm) không?","answer":"Có. Quý khách được quyền mở kiện hàng kiểm tra ngoại quan sản phẩm trước khi thanh toán cho shipper."},{"id":5,"category":"warranty","question":"Sản phẩm của Complexus có phải là hàng chính hãng 100% không?","answer":"Tất cả linh kiện đều là hàng chính hãng 100%, có tem bảo hành và hóa đơn VAT đầy đủ từ nhà phân phối."},{"id":6,"category":"warranty","question":"Nếu linh kiện bị lỗi trong quá trình sử dụng, tôi cần liên hệ ai để được hỗ trợ?","answer":"Quý khách liên hệ trực tiếp hotline hoặc mang sản phẩm đến showroom của Complexus để được kỹ thuật viên hỗ trợ nhanh nhất."}]', 'POLICY', 'Tùy biến bởi quản trị viên', 1, '2026-09-04 00:36:34', '2026-09-04 00:36:34');
